// Tests for the cells added after the two NASA panel reviews of 15 Nov 2026 (symptoms, medicines, exercise, the
// eyes), their example data, and that the example stories that were already there did not change.
// Run: npm test (Node 18+). Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createMachine, KIND, STATUS, DEST } from '../src/engine.js';
import { CELLS, SOURCES, CREW, SHIP, EFFORT } from '../src/config.js';
import { exampleFlight, exampleLogs, MISSION } from '../src/demo-crew.js';
import { assess, assessShip } from '../src/state-levels.js';
import { symptomValue, medicineValue } from '../src/quicklog.js';

const NEW = ['symptoms', 'medicines', 'exercise', 'visionCheck', 'octChange', 'octScan'];
// Blood oxygen and the thinking test had cells but no example data before; now they have some.
const NEW_DATA = [...NEW, 'spo2', 'cognition'];
const DAY = 24 * 60 * 60 * 1000;
const cell = (indicator) => CELLS.find((c) => c.indicator === indicator);
const TOM = 'crew-1';
const fixedNow = () => new Date('2026-11-15T08:00:00Z');
const make = () => createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true }, now: fixedNow });
const r = (indicator, value, person = TOM) => ({ person, source: (SOURCES.find((s) => s.indicator === indicator) || {}).id, indicator, value });
const codes = (entry) => entry.steps.map((s) => s.code);
const launch = new Date(MISSION.launch).getTime();
const flightDay = (e) => Math.floor((new Date(e.time).getTime() - launch) / DAY);
const logs = exampleLogs(CREW);
const of = (person, indicator) => logs.filter((e) => e.person === person && e.reading.indicator === indicator);

// Every { name, url } object anywhere inside a cell is a source.
const sourcesIn = (x) => (x && typeof x === 'object' ? (x.url ? [x] : Object.values(x).flatMap(sourcesIn)) : []);

function replay(events) {
  const m = make();
  for (const ev of events) {
    if (ev.kind === 'reading') m.receive({ ...ev.reading, person: ev.person, time: ev.time });
    else if (ev.kind === 'review') m.review(ev.person, ev.time);
  }
  return m;
}

// ---------- the cells ----------
test('the cells the NASA reviews found missing exist, each with label, unit, kind, effort, a sourced norm or record, and where it is available', () => {
  for (const ind of NEW) {
    const c = cell(ind);
    assert.ok(c, ind);
    assert.ok(c.label && typeof c.unit === 'string' && c.unit, `${ind}: label and unit`);
    assert.ok(Object.values(KIND).includes(c.kind), `${ind}: kind`);
    assert.ok(Object.values(EFFORT).includes(c.effort), `${ind}: effort`);
    assert.ok(typeof c.availability === 'string' && c.availability.length > 40, `${ind}: availability note`);
    assert.ok(Array.isArray(c.availabilitySrc) && c.availabilitySrc.length, `${ind}: the availability note has its source`);
    if (c.kind === KIND.NUMBER) {
      const n = c.norms[c.compareWith];
      assert.ok(n && n.text && n.src, `${ind}: the norm it uses has text and a source`);
      assert.ok(c.normType === 'record' || c.normType === 'range', ind);
    } else {
      assert.ok(c.normText && (c.src || c.kind === KIND.COMPLEX), `${ind}: norm text with a source`);
    }
    for (const s of sourcesIn(c)) {
      assert.ok(s.name, `${ind}: a source has a name`);
      assert.match(s.url, /^https:\/\/[^\s]+$/, `${ind}: ${s.url}`);
    }
    assert.ok(SOURCES.some((s) => s.indicator === ind), `${ind}: a source the technical view can simulate`);
  }
});

test('symptoms and medicines are private by default; exercise and the eyes are not', () => {
  assert.equal(cell('symptoms').private, true);
  assert.equal(cell('medicines').private, true);
  for (const ind of ['exercise', 'visionCheck', 'octChange', 'octScan']) assert.ok(!cell(ind).private, ind);
});

test('the symptom list is the one asked for, on a 0 to 10 scale', () => {
  const c = cell('symptoms');
  assert.deepEqual(c.symptoms.map((s) => s.label), ['Headache', 'Stuffy nose', 'Back pain', 'Nausea or motion sickness', 'Trouble sleeping', 'Skin', 'Eyes or vision change', 'Something else']);
  assert.deepEqual([c.severity.min, c.severity.max], [0, 10]);
  assert.equal(new Set(c.symptoms.map((s) => s.key)).size, c.symptoms.length);
  for (const s of c.symptoms.filter((x) => x.fact)) assert.ok(s.src && s.src.url, `${s.key}: a fact has its source`);
});

test('the medicine list comes from the kit list, with strength, unit and a known use; the amounts are positive', () => {
  const c = cell('medicines');
  assert.ok(c.kit.length >= 6 && c.kit.length <= 12, 'a short list');
  assert.equal(new Set(c.kit.map((k) => k.key)).size, c.kit.length);
  for (const k of c.kit) {
    assert.match(k.strength, /^\d+ (mg|mcg)$/, k.key);
    assert.equal(k.unit, 'tablet', k.key);
    assert.ok(c.uses[k.use], `${k.key}: use ${k.use}`);
  }
  assert.ok(c.kitSrc && c.kitSrc.url && c.kitDraft === true);
  assert.ok(c.amounts.every((a) => a > 0));
});

test('every threshold added here is marked as a draft', () => {
  const oct = cell('octChange');
  assert.equal(oct.draft, true);
  assert.deepEqual(oct.thresholds.map((t) => t.min), [20, 55]);
  assert.ok(oct.thresholds.every((t) => t.draft === true && t.src));
  assert.equal(oct.norm.max, oct.thresholds[0].min, 'the norm is the earliest indication');
  assert.equal(cell('symptoms').severity.draft, true);
  assert.equal(cell('visionCheck').tellDoctor.draft, true);
  const answers = cell('visionCheck').answers.map((a) => a.value);
  assert.ok(cell('visionCheck').tellDoctor.values.every((v) => answers.includes(v)));
});

// ---------- the engine takes them, only through config ----------
test('a symptom and a medicine are recorded, never judged and never sent anywhere', () => {
  const m = make();
  for (const e of [m.receive(r('symptoms', { symptom: 'headache', severity: 4 })), m.receive(r('medicines', { medicine: 'melatonin', name: 'Melatonin', strength: '3 mg', amount: 1, unit: 'tablet' }))]) {
    assert.equal(e.status, STATUS.RECORDED);
    assert.equal(e.dest, DEST.NONE);
    assert.deepEqual(codes(e), ['recorded', 'no-threshold']);
  }
  assert.equal(m.receive(r('symptoms', '')).status, STATUS.UNKNOWN);
  assert.equal(m.history(TOM, 'symptoms').length, 1);
});

test('exercise minutes are recorded, never judged', () => {
  const m = make();
  const e = m.receive(r('exercise', 75));
  assert.equal(e.status, STATUS.RECORDED);
  assert.deepEqual(codes(e), ['no-norm-recorded']);
  assert.equal(m.receive(r('exercise', 0)).status, STATUS.RECORDED, 'a rest day is a reading too');
  assert.equal(m.receive(r('exercise', 'abc')).status, STATUS.UNKNOWN);
});

test("eyes: the self-check is recorded; the OCT change leaves the draft norm at NASA's 20 microns; the scan goes to analysis", () => {
  const m = make();
  assert.equal(m.receive(r('visionCheck', 'no change')).status, STATUS.RECORDED);
  assert.equal(m.receive(r('octChange', 19)).status, STATUS.OK);
  assert.equal(m.receive(r('octChange', -4)).status, STATUS.OK, 'a thinner retina is a readable value');
  const out = m.receive(r('octChange', 20));
  assert.equal(out.status, STATUS.OUT);
  assert.equal(out.dest, DEST.AI);
  const scan = m.receive(r('octScan', 'scan'));
  assert.equal(scan.status, STATUS.ANALYSIS);
  assert.ok(codes(scan).includes('needs-analysis'));
  assert.equal(m.receive(r('octScan', ' ')).status, STATUS.UNKNOWN);
});

test('the machine refuses what the lists cannot hold: a typo for an eye answer, an unknown symptom, a medicine without a name or amount, minus minutes', () => {
  const m = make();
  const refused = [
    ['visionCheck', 'Grid changed'], ['visionCheck', 'banana'], ['visionCheck', 3],
    ['symptoms', 'junk text'], ['symptoms', { symptom: 'nope', severity: 3 }], ['symptoms', { symptom: 'headache', severity: 11 }],
    ['symptoms', { symptom: 'headache', severity: 4.5 }], ['symptoms', { symptom: 'headache', severity: '4' }], ['symptoms', { symptom: 'headache' }], ['symptoms', []],
    ['medicines', 'zolpidem'], ['medicines', { medicine: 'melatonin', amount: 0 }], ['medicines', { medicine: 'melatonin', amount: '1' }],
    ['medicines', { medicine: 'other', amount: 1 }], ['medicines', { medicine: 'other', name: '  ', amount: 1 }], ['medicines', { medicine: 'aspirin-x', amount: 1 }],
    ['exercise', -5], ['exercise', '-1'],
  ];
  for (const [ind, value] of refused) {
    const e = m.receive(r(ind, value));
    assert.equal(e.status, STATUS.UNKNOWN, `${ind} ${JSON.stringify(value)}`);
    assert.deepEqual(codes(e), ['bad-value']);
  }
  for (const ind of ['visionCheck', 'symptoms', 'medicines', 'exercise']) assert.equal(m.history(TOM, ind).length, 0, ind);
  assert.equal(m.receive(r('octChange', -4)).status, STATUS.OK, 'the OCT change may still be below zero');
});

test('everything the two quick logs and the eye answers can produce, the machine records', () => {
  const m = make();
  const sym = cell('symptoms');
  for (const s of sym.symptoms) {
    for (let n = sym.severity.min; n <= sym.severity.max; n += 1) {
      const v = symptomValue({ symptom: s.key, severity: n, note: s.needsNote ? 'sore throat' : undefined });
      assert.equal(m.receive(r('symptoms', v)).status, STATUS.RECORDED, `${s.key} ${n}`);
    }
  }
  const med = cell('medicines');
  const takenAt = new Date(fixedNow().getTime() - 2 * 3600e3).toISOString();
  for (const k of [...med.kit.map((x) => x.key), 'other']) {
    for (const amount of med.amounts) {
      const v = medicineValue({ medicine: k, amount, name: 'Eye drops', takenAt }, { now: fixedNow() });
      assert.equal(m.receive(r('medicines', v)).status, STATUS.RECORDED, `${k} ${amount}`);
    }
  }
  for (const a of cell('visionCheck').answers) assert.equal(m.receive(r('visionCheck', a.value)).status, STATUS.RECORDED, a.value);
  // And every example log is read, none refused.
  const ex = make();
  for (const e of logs) assert.notEqual(ex.receive({ ...e.reading, person: e.person, time: e.time }).status, STATUS.UNKNOWN, `${e.person} ${e.reading.indicator}`);
});

// ---------- the example data ----------
test('example logs: made up, marked so, never past today, and every value is one the logs accept', () => {
  assert.ok(logs.length > 500);
  assert.ok(logs.every((e) => e.example === true && e.kind === 'reading'));
  assert.ok(logs.every((e) => new Date(e.time) <= new Date(MISSION.today)));
  assert.ok(logs.every((e) => NEW_DATA.includes(e.reading.indicator)));
  for (const e of logs.filter((x) => x.reading.indicator === 'symptoms')) assert.deepEqual(symptomValue(e.reading.value), e.reading.value);
  for (const e of logs.filter((x) => x.reading.indicator === 'medicines')) assert.deepEqual(medicineValue(e.reading.value, { now: new Date(MISSION.today) }), e.reading.value);
  const all = exampleFlight(CREW);
  const key = (e) => JSON.stringify([e.time, e.person, e.reading.source, e.reading.indicator, e.reading.value]);
  assert.deepEqual(all.filter((e) => e.reading && NEW_DATA.includes(e.reading.indicator)).map(key).sort(), logs.map(key).sort(), 'the flight carries exactly the logs');
  const m = replay(all);
  for (const ind of NEW_DATA) for (const p of CREW) assert.ok(m.history(p.id, ind).length > 0, `${p.id} ${ind}`);
});

test('example logs: blood oxygen once a week in the norm, a thinking test once a month', () => {
  const m = make();
  for (const p of CREW) {
    const spo2 = of(p.id, 'spo2').filter((e) => flightDay(e) >= 0);
    assert.ok(spo2.length >= 20, p.id);
    for (let i = 1; i < spo2.length; i += 1) assert.equal(flightDay(spo2[i]) - flightDay(spo2[i - 1]), 7);
    for (const e of spo2) assert.equal(m.receive({ ...e.reading, person: p.id, time: e.time }).status, STATUS.OK);
    const think = of(p.id, 'cognition');
    assert.ok(think.length >= 5, p.id);
    for (let i = 1; i < think.length; i += 1) assert.equal(flightDay(think[i]) - flightDay(think[i - 1]), 30);
  }
});

test('example logs: exercise six days a week; Elly exercises least, and less as the flight goes on', () => {
  const active = (id, from = 0, to = 1e9) => of(id, 'exercise').filter((e) => e.reading.value > 0 && flightDay(e) >= from && flightDay(e) <= to).map((e) => e.reading.value);
  const mean = (list) => list.reduce((a, b) => a + b, 0) / list.length;
  for (const p of CREW) {
    const week = of(p.id, 'exercise').filter((e) => flightDay(e) >= 1 && flightDay(e) <= 7);
    assert.equal(week.length, 6, `${p.id}: six days a week, a rest day leaves no reading`);
    assert.ok(of(p.id, 'exercise').every((e) => e.reading.value >= 15 && e.reading.value <= 150), p.id);
  }
  const ellyMean = mean(active('crew-2'));
  for (const p of CREW.filter((x) => x.id !== 'crew-2')) assert.ok(mean(active(p.id)) > ellyMean + 20, p.id);
  assert.ok(mean(active('crew-2', 1, 30)) > mean(active('crew-2', 135, 170)));
});

test('example logs: headaches and a stuffy nose early in flight, back pain, and sleep aids now and then for Member 4', () => {
  for (const p of CREW) {
    const early = of(p.id, 'symptoms').filter((e) => flightDay(e) <= 2).map((e) => e.reading.value.symptom);
    assert.ok(early.includes('stuffyNose'), `${p.id}: stuffy nose early`);
    assert.ok(early.includes('headache') || early.includes('nausea'), `${p.id}: headache or motion sickness early`);
  }
  assert.ok(CREW.some((p) => of(p.id, 'symptoms').some((e) => e.reading.value.symptom === 'headache')));
  assert.ok(of('crew-2', 'symptoms').filter((e) => e.reading.value.symptom === 'backPain').every((e) => flightDay(e) <= 5), 'back pain in the first days');
  const aids = of('crew-4', 'medicines').filter((e) => ['melatonin', 'zolpidem'].includes(e.reading.value.medicine));
  assert.ok(aids.length >= 10 && aids.length <= 60, `now and then: ${aids.length}`);
  const half = Math.floor((new Date(MISSION.today).getTime() - launch) / DAY / 2);
  assert.ok(aids.filter((e) => flightDay(e) > half).length > aids.filter((e) => flightDay(e) <= half).length, 'more often late in the flight');
  const nights = new Set(aids.map((e) => flightDay(e)));
  assert.equal(nights.size, aids.length, 'never two sleep aids on one night (the kit list: do not use with other sleep meds)');
  for (const p of CREW.filter((x) => x.id !== 'crew-4')) {
    assert.ok(!of(p.id, 'medicines').some((e) => ['melatonin', 'zolpidem'].includes(e.reading.value.medicine)), `${p.id}: no sleep aid in this example`);
  }
});

test('example logs: one eye self-check a month; OCT on flight day 30, 90 and 30 days before return, all below 20 microns', () => {
  const r30 = Math.floor((new Date(MISSION.landing).getTime() - 30 * DAY - launch) / DAY);
  for (const p of CREW) {
    const checks = of(p.id, 'visionCheck');
    assert.ok(checks.length >= 5, p.id);
    for (let i = 1; i < checks.length; i += 1) assert.equal(flightDay(checks[i]) - flightDay(checks[i - 1]), 30);
    const oct = of(p.id, 'octChange');
    assert.deepEqual(oct.map((e) => flightDay(e)), [31, 91, r30 + 1], `${p.id}: the result comes the day after the scan`);
    assert.ok(oct.every((e) => e.reading.value < 20), p.id);
    assert.deepEqual(of(p.id, 'octScan').map((e) => flightDay(e)).filter((d) => d >= 0), [30, 90, r30]);
  }
});

// ---------- the old stories ----------
// Measured on main (commit 29efe5f) before this change: the example flight without the new data, counted from
// launch so it is the same at any hour. If a story is ever changed on purpose, these values change with it.
const MAIN = {
  events: 7651,
  hash: 'ab366ae6485e86911c4038fef5e647cd5918992b8b8bf7ae25ea90a166d44484',
  values: [
    ['crew-1', 'pulse', 3, 69, 2],
    ['crew-2', 'vo2max', -1, 30.7, 3967],
    ['crew-4', 'sleep', -1, 5.7, 3986],
    ['crew-4', 'mood', -1, 'bad', 3986.05],
    ['crew-3', 'hearing', -1, 15, 3609],
    ['crew-2', 'cycle', 0, 'period_start', -953],
    ['ship', 'co2', 37, 3.5, 889],
    ['crew-1', 'bp', -1, { sys: 113, dia: 68 }, 3986],
  ],
};

test('the existing example stories are unchanged: the same events, values and times as on main', () => {
  const old = exampleFlight(CREW).filter((e) => !(e.reading && NEW_DATA.includes(e.reading.indicator)));
  assert.equal(old.length, MAIN.events);
  const rows = old.map((e) => [e.kind, e.person, e.reading ? e.reading.source : null, e.reading ? e.reading.indicator : null, e.reading ? JSON.stringify(e.reading.value) : null, new Date(e.time).getTime() - launch]);
  assert.equal(createHash('sha256').update(JSON.stringify(rows)).digest('hex'), MAIN.hash);
  for (const [person, indicator, i, value, hours] of MAIN.values) {
    const list = old.filter((e) => e.person === person && e.reading && e.reading.indicator === indicator);
    const e = i < 0 ? list[list.length + i] : list[i];
    assert.deepEqual(e.reading.value, value, `${person} ${indicator}`);
    assert.equal((new Date(e.time).getTime() - launch) / 3.6e6, hours, `${person} ${indicator} time`);
  }
});

test('the new example data add nothing to Today: the same levels and items for everyone, and for the ship', () => {
  const all = exampleFlight(CREW);
  const withLogs = replay(all);
  const without = replay(all.filter((e) => !(e.reading && NEW_DATA.includes(e.reading.indicator))));
  const now = new Date(MISSION.today);
  const sum = (a) => ({ body: a.body.level, psyche: a.psyche.level, items: [...a.body.items, ...a.psyche.items].map((x) => `${x.kind} ${x.cell ? x.cell.indicator : ''} ${x.level}`) });
  for (const p of CREW) {
    assert.deepEqual(sum(assess({ machine: withLogs, person: p, cells: CELLS, mission: MISSION, now })), sum(assess({ machine: without, person: p, cells: CELLS, mission: MISSION, now })), p.id);
  }
  const ship = (m) => assessShip({ machine: m, ship: SHIP, cells: CELLS, mission: MISSION, now }).items.map((x) => x.cell.indicator);
  assert.deepEqual(ship(withLogs), ship(without));
});

test('no long dashes in the files of this change', () => {
  // The two dash characters are built from their code points, so this file holds neither of them.
  const dashes = new RegExp(`[${String.fromCharCode(0x2013, 0x2014)}]`);
  for (const f of ['src/config.js', 'src/demo-crew.js', 'src/quicklog.js', 'tests/cells.test.js', 'tests/quicklog.test.js', 'package.json']) {
    const text = readFileSync(new URL(`../${f}`, import.meta.url), 'utf8');
    assert.ok(!dashes.test(text), f);
  }
});
